-- ==============================================================================
-- Script de Synchronisation : Tarifs & Forfaits Réels de la Base d'Achraf
-- Source : rrm_db achraf (Dump officiel phpMyAdmin)
-- ==============================================================================
-- Ce script :
-- 1. Désactive temporairement FOREIGN_KEY_CHECKS pour éviter les blocages.
-- 2. Met à jour les 10 Forfaits officiels.
-- 3. Met à jour les 15 Parkings officiels de Rabat, Salé et Témara.
-- 4. Efface les anciens tarifs de `tarif_parking`.
-- 5. Insère l'ensemble des 520 tarifs officiels configurés par Achraf.
-- ==============================================================================

USE rrm_db;

SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------------------------
-- 1. Les 10 Forfaits d'Abonnement Officiels
-- ------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE 
    code = VALUES(code),
    libelle = VALUES(libelle),
    description = VALUES(description),
    place_reservee = VALUES(place_reservee),
    actif = VALUES(actif);

-- ------------------------------------------------------------------------------
-- 2. Les 15 Parkings Officiels (Rabat, Salé, Témara, Harhoura)
-- ------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE 
    code = VALUES(code),
    nom = VALUES(nom),
    adresse = VALUES(adresse),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude),
    capacite_totale = VALUES(capacite_totale),
    capacite_reservee_abonnements = VALUES(capacite_reservee_abonnements),
    statut = VALUES(statut);

-- ------------------------------------------------------------------------------
-- 3. Synchronisation des 520 Tarifs d'Achraf (Insert ou Mise à Jour Directe)
-- ------------------------------------------------------------------------------


-- ------------------------------------------------------------------------------
-- 4. Insertion des 520 tarifs complets de la base d'Achraf
-- ------------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE 
    date_creation = VALUES(date_creation),
    date_debut_validite = VALUES(date_debut_validite),
    date_fin_validite = VALUES(date_fin_validite),
    duree_en_mois = VALUES(duree_en_mois),
    prix_ht = VALUES(prix_ht),
    taux_tva = VALUES(taux_tva),
    forfait_id = VALUES(forfait_id),
    parking_id = VALUES(parking_id);

SET FOREIGN_KEY_CHECKS = 1;

COMMIT;

-- ==============================================================================
-- Fin du script : 10 Forfaits, 15 Parkings et 520 Tarifs synchronisés avec succès !
-- ==============================================================================
